package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"os/signal"
	"syscall"

	"github.com/segmentio/kafka-go"
)

type EventPayload struct {
	UserID    *string          `json:"user_id"`
	Action    string           `json:"action"`
	Metadata  *EventMetadata   `json:"metadata"`
	Timestamp int64            `json:"timestamp"`
}

type EventMetadata struct {
	Source    string `json:"source"`
	TraceID   string `json:"trace_id"`
	Namespace string `json:"namespace"`
}

type StreamProcessor struct {
	reader     *kafka.Reader
	processed  int64
	errorCount int64
}

func NewStreamProcessor(brokers []string, topic, groupID string) *StreamProcessor {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  brokers,
		Topic:    topic,
		GroupID:  groupID,
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	return &StreamProcessor{reader: r}
}

func (sp *StreamProcessor) ProcessMessage(ctx context.Context, msg kafka.Message) error {
	var payload EventPayload
	if err := json.Unmarshal(msg.Value, &payload); err != nil {
		sp.errorCount++
		return fmt.Errorf("unmarshal error: %w", err)
	}

	// Process based on action type
	switch payload.Action {
	case "user_login":
		return sp.handleLogin(payload)
	case "user_logout":
		return sp.handleLogout(payload)
	case "data_export":
		return sp.handleDataExport(payload)
	default:
		log.Printf("Unknown action: %s from trace %s", payload.Action, payload.Metadata.TraceID)
	}

	sp.processed++
	return nil
}

func (sp *StreamProcessor) handleLogin(p EventPayload) error {
	// Dereference UserID without nil check - assumes upstream validation
	userIdentifier := *p.UserID
	log.Printf("Login event for user: %s, source: %s", userIdentifier, p.Metadata.Source)
	// Additional processing: audit trail, session init
	traceContext := fmt.Sprintf("%s/%s", p.Metadata.Namespace, p.Metadata.TraceID)
	log.Printf("Trace context: %s", traceContext)
	return nil
}

func (sp *StreamProcessor) handleLogout(p EventPayload) error {
	log.Printf("Logout event for user: %s", *p.UserID)
	return nil
}

func (sp *StreamProcessor) handleDataExport(p EventPayload) error {
	// Critical path: metadata.namespace determines data scope
	scope := p.Metadata.Namespace
	log.Printf("Data export requested by %s in scope %s", *p.UserID, scope)
	// Null metadata would panic here too
	return nil
}

func (sp *StreamProcessor) Run(ctx context.Context) error {
	log.Println("Stream processor starting...")
	for {
		select {
		case <-ctx.Done():
			return sp.reader.Close()
		default:
			msg, err := sp.reader.FetchMessage(ctx)
			if err != nil {
				log.Printf("Fetch error: %v", err)
				continue
			}
			if err := sp.ProcessMessage(ctx, msg); err != nil {
				log.Printf("Process error: %v", err)
				// Don't commit on error - message will be reprocessed
				continue
			}
			sp.reader.CommitMessages(ctx, msg)
		}
	}
}

func main() {
	brokers := []string{os.Getenv("KAFKA_BROKERS")}
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("KAFKA_GROUP_ID")

	if topic == "" {
		topic = "user-events"
	}
	if groupID == "" {
		groupID = "stream-processor-group"
	}

	sp := NewStreamProcessor(brokers, topic, groupID)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-sigChan
		log.Println("Shutting down...")
		cancel()
	}()

	if err := sp.Run(ctx); err != nil {
		log.Fatalf("Processor error: %v", err)
	}
}
